
import "server-only";

import { lstat, mkdir, rename } from "fs/promises";
import path from "path";

const uploadsDirectory = path.resolve(
  process.cwd(),
  "private-uploads"
);

const quarantineDirectory = path.resolve(
  process.cwd(),
  "private-document-quarantine"
);

// Storage keys are generated by randomUUID().
const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function validateStorageKey(storageKey: string) {
  if (!UUID_PATTERN.test(storageKey)) {
    throw new Error("Invalid document storage key.");
  }
}

function documentPaths(storageKey: string) {
  validateStorageKey(storageKey);

  return {
    original: path.join(uploadsDirectory, storageKey),
    quarantined: path.join(
      quarantineDirectory,
      storageKey
    ),
  };
}

async function getFileState(
  filePath: string
): Promise<"missing" | "file"> {
  try {
    const stats = await lstat(filePath);

    if (!stats.isFile() || stats.isSymbolicLink()) {
      throw new Error("Unsafe document file type.");
    }

    return "file";
  } catch (error) {
    if (
      error instanceof Error &&
      "code" in error &&
      error.code === "ENOENT"
    ) {
      return "missing";
    }

    throw error;
  }
}

/**
 * Move a document into private quarantine.
 *
 * Safe to retry after an interrupted move.
 * Never overwrites an existing destination.
 */
export async function quarantineFinanceDocument(
  storageKey: string
) {
  const { original, quarantined } =
    documentPaths(storageKey);

  await mkdir(quarantineDirectory, {
    recursive: true,
  });

  const originalState = await getFileState(original);
  const quarantineState =
    await getFileState(quarantined);

  if (quarantineState === "file") {
    if (originalState === "file") {
      throw new Error(
        "Document exists in both storage locations."
      );
    }

    // Previous move succeeded; safe to retry.
    return;
  }

  if (originalState === "missing") {
    throw new Error(
      "Document missing from both storage locations."
    );
  }

  await rename(original, quarantined);
}

/**
 * Restore a quarantined document.
 *
 * Safe to retry when restoration has already
 * succeeded. Never overwrites an existing file.
 */
export async function restoreFinanceDocument(
  storageKey: string
) {
  const { original, quarantined } =
    documentPaths(storageKey);

  await mkdir(uploadsDirectory, {
    recursive: true,
  });

  const originalState = await getFileState(original);
  const quarantineState =
    await getFileState(quarantined);

  if (originalState === "file") {
    if (quarantineState === "file") {
      throw new Error(
        "Document exists in both storage locations."
      );
    }

    // Previously restored; safe to retry.
    return;
  }

  if (quarantineState === "missing") {
    throw new Error(
      "Document missing from both storage locations."
    );
  }

  await rename(quarantined, original);
}
